parameters.htmlMessage:
=<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>Invoice Updated | Cambay International</title>
</head>

<body style="margin:0; padding:0; background-color:#eef1f5; font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;">

  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#eef1f5; padding:50px 0;">
    <tr>
      <td align="center">

        <!-- Card -->
        <table width="620" cellpadding="0" cellspacing="0"
          style="background-color:#ffffff;
                 border-radius:12px;
                 overflow:hidden;
                 box-shadow:0 10px 30px rgba(0,0,0,0.08);">

          <!-- Top Accent (UPDATED) -->
          <tr>
            <td style="height:6px; background-color:#B7791F;"></td>
          </tr>

          <!-- Header -->
          <tr>
            <td style="padding:30px 42px; border-bottom:1px solid #eaeaea;">
              <img src="https://raw.githubusercontent.com/husen110/logoCI/main/logo.png"
                   alt="Cambay International"
                   style="height:52px; display:block;" />
            </td>
          </tr>

          <!-- Content -->
          <tr>
            <td style="padding:42px;">

              <h1 style="margin:0 0 18px 0;
                         font-size:22px;
                         font-weight:600;
                         color:#B7791F;">
                Invoice Updated
                <span style="margin-left:10px;
                             background:#F6C343;
                             color:#5C3A00;
                             padding:4px 10px;
                             border-radius:12px;
                             font-size:12px;
                             font-weight:600;">
                  UPDATED
                </span>
              </h1>

              <p style="margin:0 0 16px 0;
                        font-size:15px;
                        line-height:1.7;
                        color:#3d4a5c;">
                Dear Customer,
              </p>

              <p style="margin:0 0 16px 0;
                        font-size:15px;
                        line-height:1.7;
                        color:#3d4a5c;">
                This is to inform you that your invoice from
                <strong style="color:#0b1f33;">Cambay International</strong>
                has been <strong>updated as per your request</strong>.
              </p>

              <p style="margin:0 0 16px 0;
                        font-size:15px;
                        line-height:1.7;
                        color:#3d4a5c;">
                Please find the revised invoice attached to this email.
                Kindly review the updated details carefully.
              </p>

              <p style="margin:0 0 18px 0;
                        font-size:15px;
                        line-height:1.7;
                        color:#3d4a5c;">
                If you require any further changes or have questions regarding
                this invoice, our team will be happy to assist you.
              </p>

              <!-- Info Box (UPDATED) -->
              <table width="100%" cellpadding="0" cellspacing="0"
                style="background-color:#FFF8E6;
                       border-left:4px solid #F6C343;
                       padding:14px 18px;
                       margin:28px 0;">
                <tr>
                  <td style="font-size:14px; color:#5C3A00;">
                    This invoice has been updated electronically and does not require a signature.
                  </td>
                </tr>
              </table>

              <p style="margin:0;
                        font-size:15px;
                        line-height:1.7;
                        color:#3d4a5c;">
                Regards,<br />
                <strong style="color:#0b1f33;">Cambay International</strong>
              </p>

            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="padding:22px 42px;
                       background-color:#f9fafc;
                       border-top:1px solid #eaeaea;
                       text-align:center;">
              <p style="margin:0;
                        font-size:12px;
                        line-height:1.6;
                        color:#8a94a6;">
                This is an automated system email. Please do not reply.
              </p>
            </td>
          </tr>

        </table>
        <!-- End Card -->

      </td>
    </tr>
  </table>

</body>
</html>

