parameters.jsCode:
// ===============================
// SAFE INPUT
// ===============================
const body = $json.body || {};
const data = $json.output || $json;

// -------------------------------
// EDIT INSTRUCTION
// -------------------------------
const edit =
  typeof data.edit === 'string' && data.edit.trim()
    ? data.edit.trim()
    : '';

// -------------------------------
// ITEMS
// -------------------------------
const rawItems = Array.isArray(data.items) ? data.items : [];

const items = rawItems.map((i, idx) => {
  const quantity = Number(i.quantity) || 1;
  const rate = Number(i.rate) || 0;
  const discount = Number(i.discount) || 0;
  const unit = i.unit || 'Nos';

  let amount = quantity * rate;

  // percentage discount
  if (discount > 0 && discount <= 100) {
    amount -= (amount * discount) / 100;
  }

  // flat discount
  if (discount > 100) {
    amount -= discount;
  }

  amount = Math.max(0, Math.round(amount));

  return {
    sr: idx + 1,
    item: i.item || `Item ${idx + 1}`,
    description: i.description || '',   // ✅ ADDED
    quantity,
    unit,
    rate,
    discount,
    amount
  };
});

// -------------------------------
// TOTALS
// -------------------------------
const subtotal = items.reduce((s, i) => s + i.amount, 0);

// FIX: handle "9%" safely
const parsePercent = v =>
  Number(String(v || '').replace('%', '')) || 0;

const cgstPercent = parsePercent(data.cgstPercent || data.cgst);
const sgstPercent = parsePercent(data.sgstPercent || data.sgst);

const cgstAmount = Math.round(subtotal * cgstPercent / 100);
const sgstAmount = Math.round(subtotal * sgstPercent / 100);

const total = subtotal + cgstAmount + sgstAmount;

// -------------------------------
// BUILD ITEM ROWS HTML
// -------------------------------
let items_html = '';

items.forEach(i => {
  items_html += `
    <tr>
      <td class="center">${i.sr}</td>
      <td>
        <strong>${i.item}</strong>
        ${i.description ? `<br><small>${i.description}</small>` : ''}
      </td>
      <td class="center">${i.quantity}</td>
      <td class="center">${i.unit}</td>
      <td class="right">₹ ${i.rate}</td>
      <td class="center">${i.discount > 0 ? i.discount + '%' : '-'}</td>
      <td class="right">₹ ${i.amount}</td>
    </tr>
  `;
});

// -------------------------------
// FINAL OUTPUT (LLM FIRST, BODY FALLBACK)
// -------------------------------
return [
  {
    json: {
      invoice_no: data.invoice_no || body.invoice_no,
      date: data.date || body.date,

      customer_name: data.customer_name || body.customer_name,
      customer_email: data.customer_email || body.customer_email,
      phone_no: data.phone_no || body.phone_no,
      Gst_No: data.Gst_No || body.Gst_No,

      description: data.description || body.discription,
      term_n_condition: data.term_n_condition || body.term_n_condition,
      remark: data.remark || body.remark,

      items_html,

      subtotal,
      cgstPercent,
      cgstAmount,
      sgstPercent,
      sgstAmount,
      total,

      edit
    }
  }
];

let html = $json.items_html;

if (!html) {
  throw new Error('items_html missing');
}

// -------------------------------
// EDIT INSTRUCTION
// -------------------------------
const edit =
  typeof $json.edit === 'string' && $json.edit.trim()
    ? $json.edit.trim()
    : null;

// -------------------------------
// NORMALIZE HTML
// -------------------------------
html = html
  .replace(/\\n/g, '')
  .replace(/\n/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// -------------------------------
// HELPERS
// -------------------------------
const cleanText = (str) =>
  str.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

const toNumber = (str) =>
  Number(String(str || '').replace(/[^0-9.]/g, ''));

// -------------------------------
// EXTRACT ROWS
// -------------------------------
const rows = html.match(/<tr[^>]*>.*?<\/tr>/gi) || [];

const items = [];

for (const row of rows) {
  const cols = row.match(/<td[^>]*>.*?<\/td>/gi);
  if (!cols || cols.length < 7) continue;

  // ITEM + DESCRIPTION
  const itemCell = cols[1];

  const nameMatch = itemCell.match(/<strong>(.*?)<\/strong>/i);
  const item = nameMatch
    ? cleanText(nameMatch[1])
    : cleanText(itemCell);

  const descMatch = itemCell.match(/<small>(.*?)<\/small>/i);
  const description = descMatch ? cleanText(descMatch[1]) : '';

  const quantity = toNumber(cleanText(cols[2]));
  const unit = cleanText(cols[3]) || 'Nos';
  const rate = toNumber(cleanText(cols[4]));
  const discountRaw = cleanText(cols[5]);
  const amount = toNumber(cleanText(cols[6]));

  if (!item || isNaN(quantity) || isNaN(rate)) continue;

  // -------------------------------
  // ✅ DISCOUNT (% ONLY, SAFE)
  // -------------------------------
  let discount = 0;

  if (discountRaw.includes('%')) {
    discount = toNumber(discountRaw);

    // 🔒 HARD SAFETY CLAMP
    if (discount < 0) discount = 0;
    if (discount > 100) discount = 100;
  }

  items.push({
    item,
    description,
    quantity,
    unit,
    rate,
    discount, // ALWAYS 0–100
    amount
  });
}

// -------------------------------
// SAFETY
// -------------------------------
if (items.length === 0) {
  throw new Error('No items parsed from items_html');
}

// -------------------------------
// FINAL OUTPUT
// -------------------------------
return [
  {
    json: {
      ...$json,
      items,
      subtotal: $json.subtotal,
      total_tax: ($json.cgstAmount || 0) + ($json.sgstAmount || 0),
      currency: 'INR',
      invoice_status: 'sent',
      payment_status: $json.payment_status || 'unpaid',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      edit
    }
  }
];

