const edit =
  typeof data.edit === 'string' && data.edit.trim()
    ? data.edit.trim()
    : '';

// -------------------------------
// PAYMENT INFO (SAFE)
// -------------------------------
const payment_status =
  data.payment_status || body.payment_status || '';

const payment_method =
  data.payment_method || body.payment_method || '';

// Existing paid amount (from sheet / previous data)
const existing_amount_paid =
  Number(data.amount_paid ?? body.amount_paid) || 0;

// New payment entered by user (edit form)
const input_paid_raw = body.new_amount_paid ?? data.new_amount_paid;

// Start with existing amount
let amount_paid = existing_amount_paid;

// Add ONLY if user explicitly provides a positive number
if (
  input_paid_raw !== undefined &&
  input_paid_raw !== null &&
  input_paid_raw !== ''
) {
  const additional_paid = Number(input_paid_raw) || 0;
  if (additional_paid > 0) {
    amount_paid = existing_amount_paid + additional_paid;
  }
}

// -------------------------------
// ITEMS
// -------------------------------
const rawItems = Array.isArray(data.items) ? data.items : [];

const items = rawItems.map((i, idx) => {
  const quantity = Number(i.quantity) || 1;
  const rate = Number(i.rate) || 0;
  const discount = Number(i.discount) || 0;
  const unit = i.unit || 'Nos';

  let amount = quantity * rate;

  // percentage discount
  if (discount > 0 && discount <= 100) {
    amount -= (amount * discount) / 100;
  }

  // flat discount (legacy safety)
  if (discount > 100) {
    amount -= discount;
  }

  amount = Math.max(0, Math.round(amount));

  return {
    sr: idx + 1,
    item: i.item || `Item ${idx + 1}`,
    description: i.description || '',
    quantity,
    unit,
    rate,
    discount,
    amount
  };
});

// -------------------------------
// TOTALS
// -------------------------------
const subtotal = items.reduce((s, i) => s + i.amount, 0);

// FIX: handle "9%" safely
const parsePercent = v =>
  Number(String(v || '').replace('%', '')) || 0;

const cgstPercent = parsePercent(data.cgstPercent || data.cgst);
const sgstPercent = parsePercent(data.sgstPercent || data.sgst);

const cgstAmount = Math.round(subtotal * cgstPercent / 100);
const sgstAmount = Math.round(subtotal * sgstPercent / 100);

const total = subtotal + cgstAmount + sgstAmount;

// -------------------------------
// PAYMENT SAFETY (POST TOTAL)
// -------------------------------
// Prevent overpayment
amount_paid = Math.min(amount_paid, total);

// Remaining balance
const amount_due = Math.max(0, total - amount_paid);

// Derive payment status ONLY if not explicitly set
let final_payment_status = payment_status;

if (!final_payment_status) {
  if (amount_paid === 0) {
    final_payment_status = 'Unpaid';
  } else if (amount_paid < total) {
    final_payment_status = 'Partially Paid';
  } else {
    final_payment_status = 'Paid';
  }
}

// -------------------------------
// BUILD ITEM ROWS HTML
// -------------------------------
let items_html = '';

items.forEach(i => {
  items_html += `
    <tr>
      <td class="center">${i.sr}</td>
