// ===============================
// SAFE INPUT
// ===============================
const body = $json.body || {};
const data = $json.output || $json;

// -------------------------------
// EDIT INSTRUCTION
// -------------------------------
const edit =
  typeof data.edit === 'string' && data.edit.trim()
    ? data.edit.trim()
    : '';

// -------------------------------
// PAYMENT INFO (SAFE)
// -------------------------------
const payment_status =
  data.payment_status || body.payment_status || '';

const payment_method =
  data.payment_method || body.payment_method || '';

// Existing paid amount (from sheet / previous data)
const existing_amount_paid =
  Number(data.amount_paid ?? body.amount_paid) || 0;

// New payment entered by user (edit form)
const input_paid_raw = body.new_amount_paid ?? data.new_amount_paid;

// Start with existing amount
let amount_paid = existing_amount_paid;

// Add ONLY if user explicitly provides a positive number
if (
  input_paid_raw !== undefined &&
  input_paid_raw !== null &&
  input_paid_raw !== ''
) {
  const additional_paid = Number(input_paid_raw) || 0;
  if (additional_paid > 0) {
    amount_paid = existing_amount_paid + additional_paid;
  }
}

// -------------------------------
// ITEMS
// -------------------------------
const rawItems = Array.isArray(data.items) ? data.items : [];

const items = rawItems.map((i, idx) => {
  const quantity = Number(i.quantity) || 1;
  const rate = Number(i.rate) || 0;
  const discount = Number(i.discount) || 0;
  const unit = i.unit || 'Nos';

  let amount = quantity * rate;

  // percentage discount
  if (discount > 0 && discount <= 100) {
    amount -= (amount * discount) / 100;
  }

  // flat discount (legacy safety)
  if (discount > 100) {
    amount -= discount;
  }

  amount = Math.max(0, Math.round(amount));

  return {
    sr: idx + 1,
    item: i.item || `Item ${idx + 1}`,
    description: i.description || '',
    quantity,
    unit,
    rate,
    discount,
    amount
  };
});

// -------------------------------
// TOTALS
// -------------------------------
const subtotal = items.reduce((s, i) => s + i.amount, 0);

// FIX: handle "9%" safely
const parsePercent = v =>
  Number(String(v || '').replace('%', '')) || 0;

const cgstPercent = parsePercent(data.cgstPercent || data.cgst);
const sgstPercent = parsePercent(data.sgstPercent || data.sgst);

const cgstAmount = Math.round(subtotal * cgstPercent / 100);
const sgstAmount = Math.round(subtotal * sgstPercent / 100);

const total = subtotal + cgstAmount + sgstAmount;

// -------------------------------
// PAYMENT SAFETY (POST TOTAL)
// -------------------------------
// Prevent overpayment
amount_paid = Math.min(amount_paid, total);

// Remaining balance
const amount_due = Math.max(0, total - amount_paid);

// Derive payment status ONLY if not explicitly set
let final_payment_status = payment_status;

if (!final_payment_status) {
  if (amount_paid === 0) {
    final_payment_status = 'Unpaid';
  } else if (amount_paid < total) {
    final_payment_status = 'Partially Paid';
  } else {
    final_payment_status = 'Paid';
  }
}

// -------------------------------
// BUILD ITEM ROWS HTML
// -------------------------------
let items_html = '';

items.forEach(i => {
  items_html += `
    <tr>
      <td class="center">${i.sr}</td>
      <td>
        <strong>${i.item}</strong>
        ${i.description ? `<br><small>${i.description}</small>` : ''}
      </td>
      <td class="center">${i.quantity}</td>
      <td class="center">${i.unit}</td>
      <td class="right">₹ ${i.rate}</td>
      <td class="center">${i.discount > 0 ? i.discount + '%' : '-'}</td>
      <td class="right">₹ ${i.amount}</td>
    </tr>
  `;
});

// -------------------------------
// FINAL OUTPUT (LLM FIRST, BODY FALLBACK)
// -------------------------------
return [
  {
    json: {
      invoice_no: data.invoice_no || body.invoice_no,
      date: data.date || body.date,

      customer_name: data.customer_name || body.customer_name,
      customer_email: data.customer_email || body.customer_email,
      phone_no: data.phone_no || body.phone_no,
      Gst_No: data.Gst_No || body.Gst_No,

      description: data.description || body.discription,
      term_n_condition: data.term_n_condition || body.term_n_condition,
      remark: data.remark || body.remark,

      // PAYMENT FIELDS (SAFE)
      payment_status: final_payment_status,
      payment_method,
      amount_paid,
      amount_due,

      items_html,

      subtotal,
      cgstPercent,
      cgstAmount,
      sgstPercent,
      sgstAmount,
      total,

      edit
    }
  }
];

let html = $json.items_html;



// -------------------------------
// EDIT INSTRUCTION
// -------------------------------
const edit =
  typeof $json.edit === 'string' && $json.edit.trim()
    ? $json.edit.trim()
    : null;

// -------------------------------
// NORMALIZE HTML
// -------------------------------
html = html
  .replace(/\\n/g, '')
  .replace(/\n/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// -------------------------------
// HELPERS
// -------------------------------
const cleanText = (str) =>
  str.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

const toNumber = (str) =>
  Number(String(str || '').replace(/[^0-9.]/g, ''));

// -------------------------------
// EXTRACT ROWS
// -------------------------------
const rows = html.match(/<tr[^>]*>.*?<\/tr>/gi) || [];

const items = [];

for (const row of rows) {
  const cols = row.match(/<td[^>]*>.*?<\/td>/gi);
  if (!cols || cols.length < 7) continue;

  // ITEM + DESCRIPTION
  const itemCell = cols[1];

  const nameMatch = itemCell.match(/<strong>(.*?)<\/strong>/i);
  const item = nameMatch
    ? cleanText(nameMatch[1])
    : cleanText(itemCell);

  const descMatch = itemCell.match(/<small>(.*?)<\/small>/i);
  const description = descMatch ? cleanText(descMatch[1]) : '';

  const quantity = toNumber(cleanText(cols[2]));
  const unit = cleanText(cols[3]) || 'Nos';
  const rate = toNumber(cleanText(cols[4]));
  const discountRaw = cleanText(cols[5]);
  const amount = toNumber(cleanText(cols[6]));

  if (!item || isNaN(quantity) || isNaN(rate)) continue;

  // -------------------------------
  // DISCOUNT (% ONLY, SAFE)
  // -------------------------------
  let discount = 0;

  if (discountRaw.includes('%')) {
    discount = toNumber(discountRaw);
    if (discount < 0) discount = 0;
    if (discount > 100) discount = 100;
  }

  items.push({
    item,
    description,
    quantity,
    unit,
    rate,
    discount,
    amount
  });
}

// -------------------------------
// SAFETY
// -------------------------------
if (items.length === 0) {
  throw new Error('No items parsed from items_html');
}

// -------------------------------
// PAYMENT SAFE LOGIC
// -------------------------------

// Existing values from sheet / previous steps
const total = Number($json.total) || 0;
const existing_amount_paid = Number($json.amount_paid) || 0;

// Optional new payment (ONLY if provided upstream)
const input_paid_raw = $json.new_amount_paid;

// Start with existing amount
let amount_paid = existing_amount_paid;

if (
  input_paid_raw !== undefined &&
  input_paid_raw !== null &&
  input_paid_raw !== ''
) {
  const addPaid = Number(input_paid_raw) || 0;
  if (addPaid > 0) {
    amount_paid = existing_amount_paid + addPaid;
  }
}

// Prevent overpayment
amount_paid = Math.min(amount_paid, total);

// Remaining balance
const amount_due = Math.max(0, total - amount_paid);

// Derive payment status ONLY if missing
let payment_status = $json.payment_status;

if (!payment_status) {
  if (amount_paid === 0) {
    payment_status = 'Unpaid';
  } else if (amount_paid < total) {
    payment_status = 'Partially Paid';
  } else {
    payment_status = 'Paid';
  }
}

// -------------------------------
// FINAL OUTPUT
// -------------------------------
return [
  {
    json: {
      ...$json,

      items,

      subtotal: $json.subtotal,
      total_tax: (Number($json.cgstAmount) || 0) + (Number($json.sgstAmount) || 0),
      currency: $json.currency || 'INR',

      // PAYMENT FIELDS (SAFE)
      amount_paid,
      amount_due,
      payment_status,

      invoice_status: $json.invoice_status || 'sent',

      created_at: $json.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString(),

      edit
    }
  }
];

