parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "date": { "type": "string" },

    "due_date": {
      "type": "string",
      "description": "Payment due date in YYYY-MM-DD format. Must be explicitly provided or system-calculated and confirmed. Do not guess silently."
    },

    "purchase_invoice_no": {
      "type": "string",
      "description": "Purchase invoice number generated from Google Sheets in PINV-000 format. Never guessed or modified."
    },

    "entry_id": {
      "type": "string",
      "description": "Bank ledger entry ID fetched from the Banking Sheet and incremented sequentially (BL-000000 format). Never guessed or modified."
    },

    "source_type": {
      "type": "string",
      "description": "Ledger source type. MUST be exactly 'Purchase'. Never guessed or changed."
    },

    "direction": {
      "type": "string",
      "description": "Direction of money flow. MUST be exactly 'OUT' for purchase payments."
    },

    "vendor_name": { "type": "string" },
    "vendor_email": { "type": "string" },
    "vendor_phone": { "type": "string" },
    "vendor_address": { "type": "string" },
    "vendor_gst_no": { "type": "string" },

    "description": {
      "type": "string",
      "description": "Purchase description text provided by user or extracted from purchase invoice."
    },

    "term_n_condition": { "type": "string" },
    "remark": { "type": "string" },

    "cgst": {
      "type": "string",
      "description": "CGST percentage as text if explicitly provided (e.g. 9%)."
    },

    "sgst": {
      "type": "string",
      "description": "SGST percentage as text if explicitly provided (e.g. 9%)."
    },

    "payment_status": {
      "type": "string",
      "description": "Payment status such as Paid, Unpaid, Partially Paid. Do not guess."
    },

    "payment_method": {
      "type": "string",
      "description": "Payment method such as Cash, UPI, Bank Transfer, Card. Do not guess."
    },

    "amount_paid": {
      "type": "number",
      "description": "Total amount paid so far to vendor (cumulative)."
    },

    "edit_payment_amount": {
      "type": "number",
      "description": "ONLY the newly paid amount extracted from the current edit (e.g. 'paid 200'). MUST NOT be cumulative. Set 0 if no payment mentioned."
    },

    "amount_due": {
      "type": "number",
      "description": "Remaining amount payable to vendor. Calculated as total − amount_paid. Never negative."
    },

    "items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "item": { "type": "string" },
          "description": { "type": "string" },
          "quantity": { "type": "number" },
          "unit": { "type": "string" },
          "rate": { "type": "number" },
          "discount": { "type": "number" },
          "amount": { "type": "number" }
        },
        "required": ["item", "quantity", "rate", "amount"]
      }
    },

    "subtotal": { "type": "number" },

    "cgstPercent": { "type": "number" },
    "cgstAmount": { "type": "number" },

    "sgstPercent": { "type": "number" },
    "sgstAmount": { "type": "number" },

    "total": { "type": "number" },

    "edit": {
      "type": "string",
      "description": "Original user edit instruction or context."
    }
  },

  "required": [
    "purchase_invoice_no",
    "entry_id",
    "source_type",
    "direction",
    "vendor_name",
    "items",
    "subtotal",
    "total",
    "amount_due",
    "edit"
  ]
}

parameters.jsCode:
// ===============================
// SAFE INPUT
// ===============================
const body = $json.body || {};
const data = $json.output || $json;

// -------------------------------
// EDIT INSTRUCTION
// -------------------------------
const edit =
  typeof data.edit === 'string' && data.edit.trim()
    ? data.edit.trim()
    : '';

// -------------------------------
// PAYMENT INFO (SAFE)
// -------------------------------
const payment_status =
  data.payment_status || body.payment_status || '';

const payment_method =
  data.payment_method || body.payment_method || '';

// Existing paid amount (from sheet / previous data)
const existing_amount_paid =
  Number(data.amount_paid ?? body.amount_paid) || 0;

// New payment entered by user (edit form)
const input_paid_raw = body.new_amount_paid ?? data.new_amount_paid;

// Start with existing amount
let amount_paid = existing_amount_paid;

// Add ONLY if user explicitly provides a positive number
if (
  input_paid_raw !== undefined &&
  input_paid_raw !== null &&
  input_paid_raw !== ''
) {
  const additional_paid = Number(input_paid_raw) || 0;
  if (additional_paid > 0) {
    amount_paid = existing_amount_paid + additional_paid;
  }
}

// -------------------------------
// ITEMS
// -------------------------------
const rawItems = Array.isArray(data.items) ? data.items : [];

const items = rawItems.map((i, idx) => {
  const quantity = Number(i.quantity) || 1;
  const rate = Number(i.rate) || 0;
  const discount = Number(i.discount) || 0;
  const unit = i.unit || 'Nos';

  let amount = quantity * rate;

  // percentage discount
  if (discount > 0 && discount <= 100) {
    amount -= (amount * discount) / 100;
  }

  // flat discount (legacy safety)
  if (discount > 100) {
    amount -= discount;
  }

  amount = Math.max(0, Math.round(amount));

  return {
    sr: idx + 1,
    item: i.item || `Item ${idx + 1}`,
    description: i.description || '',
    quantity,
    unit,
    rate,
    discount,
    amount
  };
});

// -------------------------------
// TOTALS
// -------------------------------
const subtotal = items.reduce((s, i) => s + i.amount, 0);

// FIX: handle "9%" safely
const parsePercent = v =>
  Number(String(v || '').replace('%', '')) || 0;

const cgstPercent = parsePercent(data.cgstPercent || data.cgst);
const sgstPercent = parsePercent(data.sgstPercent || data.sgst);

const cgstAmount = Math.round(subtotal * cgstPercent / 100);
const sgstAmount = Math.round(subtotal * sgstPercent / 100);

const total = subtotal + cgstAmount + sgstAmount;

// -------------------------------
// PAYMENT SAFETY (POST TOTAL)
// -------------------------------
// Prevent overpayment
amount_paid = Math.min(amount_paid, total);

// Remaining balance
const amount_due = Math.max(0, total - amount_paid);

// Derive payment status ONLY if not explicitly set
let final_payment_status = payment_status;

if (!final_payment_status) {
  if (amount_paid === 0) {
    final_payment_status = 'Unpaid';
  } else if (amount_paid < total) {
    final_payment_status = 'Partially Paid';
  } else {
    final_payment_status = 'Paid';
  }
}

// -------------------------------
// BUILD ITEM ROWS HTML
// -------------------------------
let items_html = '';

items.forEach(i => {
  items_html += `
    <tr>
      <td class="center">${i.sr}</td>
      <td>
        <strong>${i.item}</strong>
        ${i.description ? `<br><small>${i.description}</small>` : ''}
      </td>
      <td class="center">${i.quantity}</td>
      <td class="center">${i.unit}</td>
      <td class="right">₹ ${i.rate}</td>
      <td class="center">${i.discount > 0 ? i.discount + '%' : '-'}</td>
      <td class="right">₹ ${i.amount}</td>
    </tr>
  `;
});

// -------------------------------
// FINAL OUTPUT (LLM FIRST, BODY FALLBACK)
// -------------------------------
return [
  {
    json: {
      invoice_no: data.invoice_no || body.invoice_no,
      date: data.date || body.date,

      customer_name: data.customer_name || body.customer_name,
      customer_email: data.customer_email || body.customer_email,
      phone_no: data.phone_no || body.phone_no,
      Gst_No: data.Gst_No || body.Gst_No,

      description: data.description || body.discription,
      term_n_condition: data.term_n_condition || body.term_n_condition,
      remark: data.remark || body.remark,

      // PAYMENT FIELDS (SAFE)
      payment_status: final_payment_status,
      payment_method,
      amount_paid,
      amount_due,

      items_html,

      subtotal,
      cgstPercent,
      cgstAmount,
      sgstPercent,
      sgstAmount,
      total,

      edit
    }
  }
];

